# and so on) as they will fail if something goes wrong.
# priv/repo/seeds.exs

# 1. Use the context functions generated by phx.gen.auth to properly hash the password
alias Ispent.Accounts
alias Ispent.Repo

Repo.delete_all(Ispent.Accounts.UserToken)
Repo.delete_all(Ispent.Accounts.User)

case Accounts.get_user_by_email("marcio@ar1mobile.com.br") do
  nil ->
    {:ok, _user} =
       Accounts.register_user(%{
    "email" => "marcio@ar1mobile.com.br",
    "password" => "abcdefghijkl"
  })

    IO.puts("Marcio user created successfully.")

  _user ->
    IO.puts("Marcio user already exists. Skipping.")
end
